svg.desc:
// clk rising edge; rst_n synchronous active-low: every register resets to 0 (state IDLE). Nets with the same label are connected.
localparam S_IDLE=3'd0, S_VALIDATE=3'd1, S_PREPARE=3'd2, S_RECEIVE=3'd3, S_DRAIN=3'd4, S_NORMALIZE=3'd5, S_DETECT=3'd6, S_REPORT=3'd7;
[bus_cfg]
cfg_in = {cfg_m_bit, cfg_nsymb, cfg_start_symbol, cfg_intra_slot_hopping, cfg_group_hopping_mode, cfg_n_id, cfg_m0, cfg_occ_i, cfg_slot_idx};  // 35 bits
[mux_snap]
snap_d = cfg_fire ? cfg_in : snap_q;
[reg_snap]
snap_q <= snap_d @(rst=35'd0);
[bus_ssp]
{m_bit_q, nsymb_q, start_symbol_q, hopping_q, gh_mode_q, n_id_q, m0_q, occ_i_q, slot_idx_q} = snap_q;
m_bit = m_bit_q; start_symbol = start_symbol_q; hopping = hopping_q; gh_mode = gh_mode_q;
n_id = n_id_q; m0 = m0_q; occ_i = occ_i_q; slot_idx = slot_idx_q;
[blk_derive]
n_data = nsymb_q[3:1];                                               // floor(L/2)
n_sf0  = hopping_q ? {1'b0, n_data[2:1]} : n_data;
n_sf1  = hopping_q ? n_data - {1'b0, n_data[2:1]} : 3'd0;
n_re   = {n_data, 3'b000} + {1'b0, n_data, 2'b00};                   // 12 * n_data (7 bits)
[blk_valid]
range_err = ((m_bit_q != 2'd1) & (m_bit_q != 2'd2)) | (nsymb_q < 4'd4) | (nsymb_q > 4'd14)
          | (start_symbol_q > 4'd10) | (({1'b0, start_symbol_q} + {1'b0, nsymb_q}) > 5'd14)
          | (gh_mode_q == 2'd3) | (m0_q > 4'd11) | (slot_idx_q > 5'd19);
occ_cfg_err = (occ_i_q >= n_sf0) | (hopping_q & (occ_i_q >= n_sf1));
[blk_check]
q_is_first = (q_expected_q == 7'd0);
q_is_last  = (q_expected_q == n_re - 7'd1);
align_ev  = cand_err | lut_err | (join_fire & (occ_err | (phase_sample_q != q_expected_q)
            | (phase_first != q_is_first) | (phase_last != q_is_last)));
order_ev  = join_fire & (y_sample_q != q_expected_q);
marker_ev = join_fire & ((y_first != q_is_first) | (y_last != q_is_last));
err_ev    = active & (align_ev | order_ev | marker_ev | num_err);
ev_code   = align_ev ? 4'd6 : order_ev ? 4'd3 : marker_ev ? 4'd4 : 4'd5;   // priority INTERNAL_ALIGN > ORDER > MARKER > NUMERIC
[cloud_next]
cfg_fire  = cfg_valid & (state_q == S_IDLE);
active    = (state_q >= S_PREPARE) & (state_q <= S_DETECT);
txn_start = (state_q == S_VALIDATE) & ~range_err & ~occ_cfg_err;
txn_clr   = err_ev | ((state_q == S_REPORT) & res_ready);
state_d   = state_q;
case (state_q)
  S_IDLE:      if (cfg_valid) state_d = S_VALIDATE;
  S_VALIDATE:  state_d = (range_err | occ_cfg_err) ? S_REPORT : S_PREPARE;
  S_PREPARE:   if (err_ev) state_d = S_REPORT; else if (gen_ready & tbl_valid) state_d = S_RECEIVE;
  S_RECEIVE:   if (err_ev) state_d = S_REPORT; else if (join_fire & q_is_last) state_d = S_DRAIN;
  S_DRAIN:     if (err_ev) state_d = S_REPORT; else if (acc_done) state_d = S_NORMALIZE;
  S_NORMALIZE: if (err_ev) state_d = S_REPORT; else if (d_valid & d_ready) state_d = S_DETECT;
  S_DETECT:    if (err_ev) state_d = S_REPORT; else if (mle_valid) state_d = S_REPORT;
  S_REPORT:    if (res_ready) state_d = S_IDLE;
  default:     state_d = S_IDLE;
endcase
err_d      = cfg_fire ? 1'b0 : ((state_q == S_VALIDATE) & (range_err | occ_cfg_err)) | err_ev ? 1'b1 : err_q;
err_code_d = cfg_fire ? 4'd0 : (state_q == S_VALIDATE) ? (range_err ? 4'd1 : occ_cfg_err ? 4'd2 : err_code_q)
                             : err_ev ? ev_code : err_code_q;
[fsm_state]
state_q <= state_d @(rst=S_IDLE);
[reg_err]
{err_q, err_code_q} <= {err_d, err_code_d} @(rst=5'd0);             // first error, held to REPORT
[op_inc]
q_inc = q_expected_q + 7'd1;
[gate_qen]
q_en = join_fire & ~err_ev;
[mux_qen]
q_run = q_en ? q_inc : q_expected_q;
[mux_qclr]
q_expected_d = cfg_fire ? 7'd0 : q_run;
[reg_qexp]
q_expected_q <= q_expected_d @(rst=7'd0);
[op_idle]
cfg_ready = (state_q == S_IDLE);
[gate_busy]
busy = ~cfg_ready;
[op_rep]
res_valid = (state_q == S_REPORT);
[op_rcv]
in_rcv = (state_q == S_RECEIVE);
[gate_yr]
y_ready = in_rcv & phase_valid;
[gate_pr]
phase_ready = in_rcv & y_valid;
[gate_jf]
join_fire = in_rcv & y_valid & phase_valid;
[blk_res]
res_error = err_q; res_error_code = err_code_q; res_m_bit = m_bit_q;
res_candidate_idx = err_q ? 2'd0 : mle_candidate_idx;   res_uci_bits = err_q ? 2'd0 : mle_uci_bits;
res_d_rx_i = err_q ? 26'd0 : mle_d_rx_i;   res_d_rx_q = err_q ? 26'd0 : mle_d_rx_q;
res_metric_best = err_q ? 43'd0 : mle_metric_best;   res_metric_second = err_q ? 43'd0 : mle_metric_second;
res_metric_gap = err_q ? 44'd0 : mle_metric_gap;
